<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM encomendas WHERE id=? AND cliente_id=?');$st->execute([$id,current_user()['id']]);$eRow=$st->fetch();if(!$eRow){http_response_code(404);exit('Encomenda não encontrada.');}$it=$pdo->prepare('SELECT ei.*,p.nome FROM encomenda_itens ei JOIN produtos p ON p.id=ei.produto_id WHERE ei.encomenda_id=?');$it->execute([$id]);$items=$it->fetchAll();include __DIR__.'/../includes/header.php'; ?><div class="page-head"><div><h1>Encomenda <?=e($eRow['numero'])?></h1><?=status_badge($eRow['status'])?></div><a class="btn secondary" href="imprimir.php?id=<?=$id?>">Imprimir</a></div><div class="card"><p><strong>Data:</strong> <?=datetime_br($eRow['data_hora'])?></p><p><strong>Origem:</strong> <?=e($eRow['origem'])?></p><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['nome'])?></td><td><?=e($i['quantidade'])?></td><td><?=money($i['preco_unitario'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="total-line total"><span>Total</span><strong><?=money($eRow['total'])?></strong></div><p><strong>Observações:</strong><br><?=nl2br(e($eRow['observacoes']))?></p></div><?php include __DIR__.'/../includes/footer.php'; ?>
